 function termsHtml(){const issuer=payload.issuer;return `<p class="quick-hint">Ez a lépés teljesen kihagyható. A kitöltött adatok rákerülnek a PDF-re.</p><div class="grid">${field('issued_on','Dátum',payload.issued_on,'date')}${field('valid_until','Érvényesség',payload.valid_until,'date')}${field('survey_date','Felmérés dátuma',payload.survey_date||'','date')}${field('execution_period','Kivitelezés tervezett ideje',payload.execution_period||'','text','maxlength="200"')}</div><div data-terms-templates></div><label>Az ajánlatra vonatkozó fontos információk<textarea data-field="terms" maxlength="5000">${esc(payload.terms)}</textarea></label><details><summary>Fejléc és lábléc adatai</summary><div class="grid">${field('issuer.name','Ajánlatadó neve',issuer.name,'text','maxlength="120"')}${field('issuer.address','Cím / székhely',issuer.address,'text','maxlength="180"')}${field('issuer.tax_number','Adószám',issuer.tax_number,'text','maxlength="40"')}${field('issuer.email','Kapcsolati email',issuer.email,'email','maxlength="120"')}${field('issuer.phone','Telefon',issuer.phone,'tel','maxlength="80"')}</div></details>`;}
