 async function performSave(){if(editor&&editorDirty)commitEditor();if(!dirty)return record;const token=epoch,snapshot=structuredClone(payload);const next=await rpc('quote_quick_save',{p_id:id,p_payload:snapshot,p_revision:revision});if(token!==epoch)return;record=next;revision=next.revision;number=next.number;promoted=next.promoted_quote_id;dirty=JSON.stringify(snapshot)!==JSON.stringify(payload);if(!dirty)payload=structuredClone(next.payload);saved=[next,...saved.filter(d=>d.id!==id)].slice(0,100);return next;}
